CREATE COLUMN TABLE "TEST_AP"."@SC_HANACONNECT" ("Code" NVARCHAR(50) NOT NULL , "Name" NVARCHAR(100) NOT NULL , "U_Host" NVARCHAR(128), "U_Port" NVARCHAR(10), "U_DbName" NVARCHAR(128), "U_Schema" NVARCHAR(128), "U_RmUser" NVARCHAR(128), "U_Password" NVARCHAR(254), PRIMARY KEY ("Code")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "KSC_HANACONNECT_NAME" ON "TEST_AP"."@SC_HANACONNECT" ( "Name" ASC )